import hashlib,json,os,pathlib,shutil,subprocess,sys,tempfile
import numpy as np
root=pathlib.Path.cwd()
cases=[('checksum','INPUT_CORRUPT'),('escape','PATH_INVALID'),('all_invalid','NO_VALID_DEPTH'),('shape','DEPTH_SHAPE_INVALID'),('depth_dtype','DEPTH_DTYPE_INVALID'),('mask_dtype','DEPTH_DTYPE_INVALID'),('intrinsics','INTRINSICS_INVALID'),('canonical_violation','DEPTH_VALUES_INVALID'),('empty','MANIFEST_INVALID'),('duplicate','MANIFEST_INVALID'),('bad_json','JSONDecodeError'),('missing_arrays','FileNotFoundError'),('expected_mismatch','RESULT_INVALID'),('repeat_zero','usage')]
failures=0
for kind,expected in cases:
    with tempfile.TemporaryDirectory() as tmp:
        base=pathlib.Path(tmp); session=base/'session'; shutil.copytree(root/'examples/synthetic',session)
        meta_path=session/'frame_000001/metadata.json'; arrays_path=meta_path.parent/'arrays.npz'; manifest=session/'frames.jsonl'
        meta=json.loads(meta_path.read_text(encoding='utf-8'))
        with np.load(arrays_path) as a: depth=a['depth_m']; mask=a['valid_mask']
        extra=[]
        if kind=='checksum': arrays_path.write_bytes(b'corrupt')
        elif kind=='escape': manifest.write_text(json.dumps({'frame_id':'x','metadata_path':'../outside.json'}),encoding='utf-8')
        elif kind=='empty': manifest.write_text('',encoding='utf-8')
        elif kind=='duplicate': manifest.write_text(manifest.read_text(encoding='utf-8')*2,encoding='utf-8')
        elif kind=='bad_json': manifest.write_text('{broken',encoding='utf-8')
        elif kind=='missing_arrays': arrays_path.unlink()
        elif kind=='intrinsics':
            meta['intrinsics']['width']=4; meta_path.write_text(json.dumps(meta),encoding='utf-8')
        elif kind=='expected_mismatch':
            expected_path=base/'expected.json'; expected_path.write_text('[[0,0,2],[0.01,0,1],[0,0.01,1]]',encoding='utf-8'); extra=['--expected-points',str(expected_path)]
        elif kind=='repeat_zero': extra=['--repeat','0']
        else:
            if kind=='all_invalid': depth[:]=0; mask[:]=False
            elif kind=='shape': mask=mask[:1]
            elif kind=='depth_dtype': depth=depth.astype(np.float64)
            elif kind=='mask_dtype': mask=mask.astype(np.uint8)
            elif kind=='canonical_violation': depth[1,1]=2
            np.savez(arrays_path,depth_m=depth,valid_mask=mask)
            meta['storage']['sha256']=hashlib.sha256(arrays_path.read_bytes()).hexdigest()
            meta_path.write_text(json.dumps(meta),encoding='utf-8')
        before={p.relative_to(session).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in session.rglob('*') if p.is_file()}
        report=base/'replay.json'
        cmd=[sys.executable,'-X','utf8','src/replay.py',str(session),'--repeat','2','--report',str(report),*extra]
        result=subprocess.run(cmd,cwd=root,env={**os.environ,'PYTHONUTF8':'1'},capture_output=True,text=True,encoding='utf-8')
        after={p.relative_to(session).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in session.rglob('*') if p.is_file()}
        record=json.loads(report.read_text(encoding='utf-8')) if report.exists() else None
        actual=(record['errors'][0]['code'] or record['errors'][0].get('exception_type')) if record else 'usage'
        matched=actual==expected and result.returncode==(2 if kind=='repeat_zero' else 1) and before==after
        failures+=not matched
        print(json.dumps({'case':kind,'command':cmd,'expected_error':expected,'actual_error':actual,'exit_code':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'input_unchanged':before==after,'passed':matched},ensure_ascii=False))
print(json.dumps({'failure_cli_cases':len(cases),'passed':len(cases)-failures,'failed':failures}))
sys.exit(1 if failures else 0)

